function dMixed(rods,reels,lo,hi,skipBs){const out=[];const rs=reels.slice().sort((x,y)=>x.pr-y.pr);
rods.forEach(b=>{const l=b.pr*(.4/.6),h=b.pr;let n=0;for(const r of rs){if(r.pr<l)continue;if(r.pr>h)break;if(r.bs===b.bs)continue;const t=b.pr+r.pr;if(t>=lo&&t<=hi){out.push({b,r,t,q:b.pr/t,same:false});if(++n>=3)break}}});return out}
